 async function replaceMap(load,message){if(!replacementAllowed())return false;const original=getProject();replacing=true;replacementStatus();const buttons=[...root.querySelectorAll('#me-generate,#me-japan,#me-battlefield-load,#me-quick-load,#me-library-load,#me-import')],disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{const apply=await load(original);if(getProject()!==original)throw Error('読み込み中に地図が変更されました。編集を保護するため中止しました。もう一度読み込んでください。');let links=0;const ok=doChange(p=>{apply(p);links=reconcileMapReferences(p);});if(ok===false)return false;$('me-replace').checked=false;view={x:0,y:0};zoom=1;draw();tell(message+(links?' 削除された施設への武装補給リンクを解除し、予備弾を0にしました。':''));return true;}catch(e){tell(e.message);return false;}finally{replacing=false;buttons.forEach((b,i)=>b.disabled=disabled[i]);replacementStatus();}}
