 function pos(e){const rect=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1000,view.x+(e.clientX-rect.left)/rect.width*1000/zoom)),y:Math.max(0,Math.min(1000,(view.y+(e.clientY-rect.top)/rect.height*625/zoom)/.625))};}
