 function facilitySpec(){return{type:$('me-facility').value,name:$('me-name').value,team:$('me-team').value,radiusKm:Number($('me-radius-km').value),blockKm:Number($('me-block-km').value),buildingHeight:Number($('me-building-height').value)};}
 function newFacility(p,points,spec=facilitySpec()){if(p.facilities.length>=1000)throw Error('設備は1000件までです。');let n=1;while(p.facilities.some(f=>f.id==='map-f'+n))n++;const type=spec.type;p.facilities.push({id:'map-f'+n,...spec,defense:['trench','bunker','fort'].includes(type)?100:0,damage:type==='minefield'?100:0,points,repairRate:0,supportRate:['hospital','army_base','naval_base','airfield'].includes(type)?1:0});}
